-- Public projections and private generation records; all fixtures roll back.
begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
select is((select string_agg(attname,',' order by attname) from pg_attribute where attrelid='public.generations'::regclass and attnum>0 and not attisdropped and has_column_privilege('authenticated',attrelid,attnum,'SELECT')),'category,created_at,creation_mode,duration,id,prediction_id,status,user_id','authenticated generations: exact column allowlist');
select is((select string_agg(attname,',' order by attname) from pg_attribute where attrelid='public.templates'::regclass and attnum>0 and not attisdropped and has_column_privilege('anon',attrelid,attnum,'SELECT')),'active_version_id,category,created_at,creator_user_id,description,id,input_slots,is_active,name,output_kind,slug,status,thumbnail_url,updated_at,use_count,video_url','anon templates: exact column allowlist');
select is((select string_agg(attname,',' order by attname) from pg_attribute where attrelid='public.templates'::regclass and attnum>0 and not attisdropped and has_column_privilege('authenticated',attrelid,attnum,'SELECT')),'active_version_id,category,created_at,creator_user_id,description,id,input_slots,is_active,name,output_kind,slug,status,thumbnail_url,updated_at,use_count,video_url','authenticated templates: exact column allowlist');
select ok(not has_any_column_privilege('anon','public.template_versions','SELECT') and not has_any_column_privilege('authenticated','public.template_versions','SELECT'),'template_versions: internal graph/job records have no client-readable columns');
select ok(not has_any_column_privilege('anon','public.template_runs','SELECT') and not has_any_column_privilege('authenticated','public.template_runs','SELECT'),'template_runs: internal graph/job records have no client-readable columns');
select ok(not has_any_column_privilege('anon','public.template_run_steps','SELECT') and not has_any_column_privilege('authenticated','public.template_run_steps','SELECT'),'template_run_steps: internal graph/job records have no client-readable columns');
select ok(not has_any_column_privilege('anon','public.generation_completion_jobs','SELECT') and not has_any_column_privilege('authenticated','public.generation_completion_jobs','SELECT'),'generation_completion_jobs: internal graph/job records have no client-readable columns');
select ok(not has_any_column_privilege('anon','public.generation_output_import_jobs','SELECT') and not has_any_column_privilege('authenticated','public.generation_output_import_jobs','SELECT'),'generation_output_import_jobs: internal graph/job records have no client-readable columns');
insert into auth.users(id,email,aud,role,created_at) values('e5100001-0000-4000-8000-000000000001','projection-1@example.invalid','authenticated','authenticated',now());
insert into auth.sessions(id,user_id,created_at,updated_at) values('e5100001-0000-4000-8000-000000000001','e5100001-0000-4000-8000-000000000001',now(),now());
insert into public.ai_usage_events(user_id,feature,provider,model,status) values('e5100001-0000-4000-8000-000000000001','audit-projection','inert','no-provider','succeeded');
insert into auth.users(id,email,aud,role,created_at) values('e5100002-0000-4000-8000-000000000002','projection-2@example.invalid','authenticated','authenticated',now());
insert into auth.sessions(id,user_id,created_at,updated_at) values('e5100002-0000-4000-8000-000000000002','e5100002-0000-4000-8000-000000000002',now(),now());
insert into public.ai_usage_events(user_id,feature,provider,model,status) values('e5100002-0000-4000-8000-000000000002','audit-projection','inert','no-provider','succeeded');
insert into public.generations(id,user_id,model,status,is_public) values('e5200000-0000-4000-8000-000000000001','e5100001-0000-4000-8000-000000000001','audit-projection-no-provider','succeeded',false);
insert into public.generations(id,user_id,model,status,is_public) values('e5200000-0000-4000-8000-000000000002','e5100002-0000-4000-8000-000000000002','audit-projection-no-provider','succeeded',false);
insert into public.generations(id,user_id,model,status,is_public) values('e5200000-0000-4000-8000-000000000003','e5100002-0000-4000-8000-000000000002','audit-projection-no-provider','succeeded',true);
insert into public.generation_input_media(generation_id,user_id,media_type,role,storage_path) values('e5200000-0000-4000-8000-000000000001','e5100001-0000-4000-8000-000000000001','image','reference','audit-projection/1');
insert into public.generation_input_media(generation_id,user_id,media_type,role,storage_path) values('e5200000-0000-4000-8000-000000000002','e5100001-0000-4000-8000-000000000001','image','reference','audit-projection/2');
insert into public.templates(id,name,creator_user_id,status,is_active) values('e5300000-0000-4000-8000-000000000001','Audit projection','e5100002-0000-4000-8000-000000000002','active',true);
insert into public.templates(id,name,creator_user_id,status,is_active) values('e5300000-0000-4000-8000-000000000002','Audit projection','e5100001-0000-4000-8000-000000000001','draft',true);
insert into public.templates(id,name,creator_user_id,status,is_active) values('e5300000-0000-4000-8000-000000000003','Audit projection','e5100002-0000-4000-8000-000000000002','draft',true);
insert into public.source_tools(id,slug,label,is_active) values('e5200000-0000-4000-8000-000000000001','audit-projection-1','Audit projection',true);
insert into public.source_tool_models(source_tool_id,slug,label,is_active) values('e5200000-0000-4000-8000-000000000001','audit-projection-1','Audit projection',true);
insert into public.source_tools(id,slug,label,is_active) values('e5200000-0000-4000-8000-000000000002','audit-projection-2','Audit projection',false);
insert into public.source_tool_models(source_tool_id,slug,label,is_active) values('e5200000-0000-4000-8000-000000000001','audit-projection-2','Audit projection',false);
insert into public.follows(follower_id,following_id) values('e5100001-0000-4000-8000-000000000001','e5100002-0000-4000-8000-000000000002');
insert into public.templates(id,name,creator_user_id,status,is_active) values
('e5300000-0000-4000-8000-000000000004','Audit projection','e5100002-0000-4000-8000-000000000002','disabled',true),
('e5300000-0000-4000-8000-000000000005','Audit projection','e5100002-0000-4000-8000-000000000002','active',false),
('e5300000-0000-4000-8000-000000000006','Audit projection',null,'active',true);
set local role anon;
select is((select count(*) from public.source_tools where slug like 'audit-projection-%'),1::bigint,'public tools expose only active entries');
select is((select count(*) from public.source_tool_models where slug like 'audit-projection-%'),1::bigint,'public source models expose only active entries');
select is((select count(id) from public.templates where name='Audit projection'),1::bigint,'anonymous templates expose only published fixture');
select is((select count(*) from public.follows where follower_id='e5100001-0000-4000-8000-000000000001'),1::bigint,'follow relationship is intentionally public');
select throws_ok($$ select id from public.generation_input_media $$,'42501',null,'anonymous generation_input_media read denied');
select throws_ok($$ select id from public.ai_usage_events $$,'42501',null,'anonymous ai_usage_events read denied');
select throws_ok($$ select id from public.generations $$,'42501',null,'anonymous generations read denied');
reset role;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"e5100001-0000-4000-8000-000000000001","role":"authenticated","session_id":"e5100001-0000-4000-8000-000000000001"}',true);
select is((select count(id) from public.generations),1::bigint,'direct generations expose only own metadata even if foreign generation is public');
select is((select count(*) from public.generation_input_media),1::bigint,'input media requires child and parent ownership');
select is((select count(*) from public.ai_usage_events),1::bigint,'usage events expose only owner records');
select is((select count(id) from public.templates where name='Audit projection'),2::bigint,'registered owner sees public and own draft template');
select throws_ok($$ select prompt from public.generations $$,'42501',null,'direct generation prompt excluded from projection');
select throws_ok($$ select * from public.templates $$,'42501',null,'template full-row read is not allowed');
select throws_ok($$ update public.generation_input_media set label='forged' where false $$,'42501',null,'direct generation_input_media writes denied');
with changed as (update public.ai_usage_events set input_prompt='forged' returning id) select is((select count(*) from changed),0::bigint,'RLS prevents direct ai_usage_events writes');
with changed as (update public.source_tools set label='forged' returning id) select is((select count(*) from changed),0::bigint,'RLS prevents direct source_tools writes');
with changed as (update public.source_tool_models set label='forged' returning id) select is((select count(*) from changed),0::bigint,'RLS prevents direct source_tool_models writes');
select throws_ok($$ update public.templates set name='forged' where false $$,'42501',null,'direct templates writes denied');
select throws_ok($$ insert into public.ai_usage_events (user_id,feature,provider,model) values('e5100001-0000-4000-8000-000000000001','forged','inert','inert') $$,'42501',null,'ai_usage_events: direct insert rejected');
select throws_ok($$ insert into public.source_tools (slug,label) values('audit-forged-tool','forged') $$,'42501',null,'source_tools: direct insert rejected');
select throws_ok($$ insert into public.source_tool_models (source_tool_id,slug,label) values('e5200000-0000-4000-8000-000000000001','audit-forged-model','forged') $$,'42501',null,'source_tool_models: direct insert rejected');
select throws_ok($$ insert into public.templates (name) values('forged') $$,'42501',null,'templates: direct insert rejected');
select throws_ok($$ insert into public.follows (follower_id,following_id) values('e5100002-0000-4000-8000-000000000002','e5100001-0000-4000-8000-000000000001') $$,'42501',null,'follows: direct insert rejected');
select throws_ok($$ insert into public.generation_input_media (generation_id,user_id,media_type,role,storage_path) values('e5200000-0000-4000-8000-000000000001','e5100001-0000-4000-8000-000000000001','image','reference','forged') $$,'42501',null,'generation_input_media: direct insert rejected');
select throws_ok($$ insert into public.generations (user_id,model) values('e5100001-0000-4000-8000-000000000001','inert') $$,'42501',null,'generations: direct insert rejected');
select throws_ok($$ delete from public.generations $$,'42501',null,'generations: direct delete rejected');
select throws_ok($$ delete from public.generation_input_media $$,'42501',null,'generation_input_media: direct delete rejected');
select throws_ok($$ delete from public.templates $$,'42501',null,'templates: direct delete rejected');
select throws_ok($$ delete from public.follows $$,'42501',null,'follows: direct delete rejected');
with changed as (delete from public.source_tools returning id) select is((select count(*) from changed),0::bigint,'source_tools: RLS prevents direct deletion');
with changed as (delete from public.source_tool_models returning id) select is((select count(*) from changed),0::bigint,'source_tool_models: RLS prevents direct deletion');
with changed as (delete from public.ai_usage_events returning id) select is((select count(*) from changed),0::bigint,'ai_usage_events: RLS prevents direct deletion');
reset role;
update auth.users set banned_until=now()+interval '1 hour' where id='e5100001-0000-4000-8000-000000000001';
set local role authenticated;
select is((select count(id) from public.generations),0::bigint,'generations: banned identity reads no rows');
select is((select count(id) from public.generation_input_media),0::bigint,'generation_input_media: banned identity reads no rows');
select is((select count(id) from public.ai_usage_events),0::bigint,'ai_usage_events: banned identity reads no rows');
select is((select count(id) from public.templates),0::bigint,'templates: banned identity reads no rows');
select is((select count(id) from public.source_tools),0::bigint,'source_tools: banned identity reads no rows');
select is((select count(id) from public.source_tool_models),0::bigint,'source_tool_models: banned identity reads no rows');
reset role;
update auth.users set banned_until=null,is_anonymous=true where id='e5100001-0000-4000-8000-000000000001';
set local role authenticated;
select is((select count(id) from public.generations),1::bigint,'generations: active guest retains own generation-related data');
select is((select count(id) from public.generation_input_media),1::bigint,'generation_input_media: active guest retains own generation-related data');
select is((select count(id) from public.ai_usage_events),1::bigint,'ai_usage_events: active guest retains own generation-related data');
reset role;
update auth.users set is_anonymous=false where id='e5100001-0000-4000-8000-000000000001';
set local role authenticated;
reset role;
delete from auth.sessions where id='e5100001-0000-4000-8000-000000000001';
set local role authenticated;
select is((select count(id) from public.generations),0::bigint,'revoked session cannot read generations');
select is((select count(id) from public.generation_input_media),0::bigint,'revoked session cannot read generation_input_media');
select is((select count(id) from public.ai_usage_events),0::bigint,'revoked session cannot read ai_usage_events');
reset role;
select * from finish();
rollback;
